"Borrar": "Esborra",
"Puedes corregirlo o borrarlo hasta {DIES_CORREGIR} días después.": "El pots corregir o esborrar fins a {DIES_CORREGIR} dies després.",
"Cuerpo": "Cos",
"Resumen de tu fuerza": "Resum de la teva força",
"Tu fuerza para tu peso, comparada con la gente de KLONK, día a día desde el {fechaCorta}: de {v} a {v2} ({x}{canvi}). Sube cuando levantas más, y se mueve un poco cuando entra gente nueva.": "La teva força per al teu pes, comparada amb la gent de KLONK, dia a dia des del {fechaCorta}: de {v} a {v2} ({x}{canvi}). Puja quan aixeques més, i es mou una mica quan entra gent nova.",
"De frente": "De cara",
"De espaldas": "D'esquena",
"Con unas 30 series en las últimas 4 semanas verás tu homúnculo: el cuerpo según lo que entrenas.": "Amb unes 30 sèries en les últimes 4 setmanes veuràs el teu homuncle: el cos segons el que entrenes.",
"Vas equilibrado: ningún grupo se come a su contrario.": "Vas equilibrat: cap grup es menja el seu contrari.",
"Cada músculo, del tamaño de lo que lo entrenas en las últimas 4 semanas: naranja, de más; lila, de menos.": "Cada múscul, de la mida del que l'entrenes en les últimes 4 setmanes: taronja, de més; lila, de menys.",
"Tus medidas, con PRO": "Les teves mesures, amb PRO",
"Tu peso y tus medidas, semana a semana. Lo que ya apuntaste se guarda.": "El teu pes i les teves mesures, setmana a setmana. El que ja vas apuntar es desa.",
