"Reservar": "Reserva",
"La ropa de KLONK, para ir al gimnasio con tu clan. Las fotos y los modelos están creados con IA.": "La roba de KLONK, per anar al gimnàs amb el teu clan. Les fotos i els models estan fets amb IA.",
"La ropa de KLONK, para ir al gimnasio con tu clan. Resérvala con tu talla: no pagas nada y te avisamos cuando esté a la venta. Las fotos y los modelos están creados con IA.": "La roba de KLONK, per anar al gimnàs amb el teu clan. Reserva-la amb la teva talla: no pagues res i t'avisem quan estigui a la venda. Les fotos i els models estan fets amb IA.",
