"Revisa los números: en 100 g no caben tantos (máximo 900 kcal y 100 g entre proteínas, hidratos y grasas).": "Revisa els números: en 100 g no n'hi caben tants (màxim 900 kcal i 100 g entre proteïnes, hidrats i greixos).",
"Guardado en tus alimentos.": "Desat als teus aliments.",
"«{n}» borrado. Lo que ya apuntaste se queda.": "«{n}» esborrat. El que ja has apuntat es queda.",
"Es una orientación a partir de lo que apuntas, no un consejo médico.": "És una orientació a partir del que apuntes, no un consell mèdic.",
"Cómo vas comiendo": "Com vas menjant",
"Apunta lo que comes dos días y aquí te decimos cómo vas: la proteína, cómo la repartes, la energía y la fruta y la verdura.": "Apunta el que menges dos dies i aquí et diem com vas: la proteïna, com la reparteixes, l'energia i la fruita i la verdura.",
"{pDia} g al día de media. Pon tu peso en Ajustes y te decimos si es suficiente.": "{pDia} g al dia de mitjana. Posa el teu pes a Configuració i et diem si n'hi ha prou.",
"Vas bien: {pDia} g al día de media, y lo que te ayuda a ganar fuerza es a partir de {lo} g.": "Vas bé: {pDia} g al dia de mitjana, i el que t'ajuda a guanyar força és a partir de {lo} g.",
"Casi: {pDia} g al día de media, y lo que te ayuda es a partir de {lo} g. Un lácteo, unos huevos o un poco más de carne o legumbre en una comida lo arregla.": "Gairebé: {pDia} g al dia de mitjana, i el que t'ajuda és a partir de {lo} g. Un làctic, uns ous o una mica més de carn o llegum en un àpat ho arregla.",
"Te falta: {pDia} g al día de media, y lo que te ayuda a ganar fuerza es a partir de {lo} g. Pon algo de proteína en cada comida: lácteos, huevos, carne, pescado o legumbres.": "Te'n falta: {pDia} g al dia de mitjana, i el que t'ajuda a guanyar força és a partir de {lo} g. Posa una mica de proteïna a cada àpat: làctics, ous, carn, peix o llegums.",
"Cómo la repartes": "Com la reparteixes",
"Bien repartida: {x} comidas al día con 20 g o más.": "Ben repartida: {x} àpats al dia amb 20 g o més.",
"Mejor en tres o cuatro comidas con 20 a 40 g cada una que casi toda en una: ahora son {x} al día.": "Millor en tres o quatre àpats amb entre 20 i 40 g cadascun que gairebé tota en un: ara en són {x} al dia.",
"La energía": "L'energia",
"Equilibrada: {c} % de hidratos, {g} % de grasas y {p} % de proteína.": "Equilibrada: {c} % d'hidrats, {g} % de greixos i {p} % de proteïna.",
"Pocos hidratos para entrenar fuerte ({c} %; lo normal es de 45 a 65 %). Arroz, pasta, pan, patata o fruta son tu gasolina.": "Pocs hidrats per entrenar fort ({c} %; el normal és del 45 al 65 %). Arròs, pasta, pa, patata o fruita són la teva gasolina.",
"Bastante grasa ({g} %; lo normal es de 20 a 35 %). Revisa los fritos, la bollería y las salsas.": "Força greix ({g} %; el normal és del 20 al 35 %). Revisa els fregits, la brioixeria i les salses.",
"Fruta y verdura": "Fruita i verdura",
"Bien: unas {x} al día. La meta es cinco.": "Bé: unes {x} al dia. La meta és cinc.",
"Unas {x} al día de las que apuntas; la meta es cinco. Una pieza de fruta en el desayuno y verdura en la comida y la cena ya casi lo es.": "Unes {x} al dia de les que apuntes; la meta és cinc. Una peça de fruita a l'esmorzar i verdura al dinar i al sopar, i ja gairebé hi ets.",
"Energía: {p} % proteína, {c} % hidratos, {g} % grasas": "Energia: {p} % proteïna, {c} % hidrats, {g} % greixos",
