"Tu yunque sale de tu <b>fuerza</b>: en cada ejercicio comparamos lo que levantas <b>para tu peso</b> (la fuerza relativa) con lo de todos los que lo hacen en KLONK, y tu fuerza es la media de esos puestos, de 0 a 1000. Por eso alguien ligero que levanta mucho para lo que pesa puede estar muy arriba.": "La teva enclusa surt de la teva <b>força</b>: a cada exercici comparem el que aixeques <b>per al teu pes</b> (la força relativa) amb el de tots els que el fan a KLONK, i la teva força és la mitjana d'aquestes posicions, de 0 a 1000. Per això algú lleuger que aixeca molt per al que pesa pot estar molt amunt.",
