"Es una estimación. Si tienes una enfermedad, estás embarazada o te cuesta comer, habla con un profesional.": "És una estimació. Si tens una malaltia, estàs embarassada o et costa menjar, parla amb un professional.",
"Cómo lo calculamos": "Com ho calculem",
"Está por debajo de tu metabolismo basal ({n} kcal): es poco para entrenar.": "És per sota del teu metabolisme basal ({n} kcal): és poc per entrenar.",
"Son más de 500 kcal menos que tu gasto: así cuesta conservar el músculo (Murphy y Koehler, 2022).": "Són més de 500 kcal menys que la teva despesa: així costa conservar el múscul (Murphy i Koehler, 2022).",
"Son más de un 20 % por encima de tu gasto: sumarías más grasa que músculo (Iraki y otros, 2019).": "És més d'un 20 % per sobre de la teva despesa: sumaries més greix que múscul (Iraki i altres, 2019).",
"Tu objetivo: {n} kcal al día.": "El teu objectiu: {n} kcal al dia.",
"Revisado el 03-10-2026.": "Revisat el 03-10-2026.",
"El metabolismo basal, con la fórmula de Mifflin-St Jeor (Mifflin y otros, Am J Clin Nutr, 1990): 10 × peso + 6,25 × altura − 5 × edad, + 5 los hombres y − 161 las mujeres.": "El metabolisme basal, amb la fórmula de Mifflin-St Jeor (Mifflin i altres, Am J Clin Nutr, 1990): 10 × pes + 6,25 × alçada − 5 × edat, + 5 els homes i − 161 les dones.",
"Lo que te mueves fuera del gym, con el factor de actividad de la FAO, la OMS y la UNU (2004): poco 1,40; algo 1,53; bastante 1,76; mucho 2,00.": "El que et mous fora del gimnàs, amb el factor d'activitat de la FAO, l'OMS i la UNU (2004): poc 1,40; una mica 1,53; bastant 1,76; molt 2,00.",
"Cada día de gym suma 3,5 MET durante lo que suelen durar tus entrenos, {min} min (Compendio de actividades físicas, 2024), repartido entre los siete días.": "Cada dia de gimnàs suma 3,5 MET durant el que solen durar els teus entrenaments, {min} min (Compendi d'activitats físiques, 2024), repartit entre els set dies.",
