"Lava el arroz hasta que el agua salga clara. Ponlo en una olla con el doble de agua y una pizca de sal y, cuando hierva, baja el fuego, tapa y déjalo 12 minutos. Luego apaga el fuego y deja que repose tapado.": "Renta l'arròs fins que l'aigua surti clara. Posa'l en una olla amb el doble d'aigua i un pessic de sal i, quan bulli, abaixa el foc, tapa'l i deixa'l 12 minuts. Després apaga el foc i deixa'l reposar tapat.",
"Corta el pollo en dados de dos o tres centímetros y sazónalo con un poco de sal.": "Talla el pollastre a daus de dos o tres centímetres i sala'l una mica.",
"Calienta una sartén a fuego medio con la cucharada de aceite y dora el pollo 4 minutos, dándole la vuelta a media cocción. Añade el curry y remueve un minuto más.": "Escalfa una paella a foc mitjà amb la cullerada d'oli i daura el pollastre 4 minuts, girant-lo a mitja cocció. Afegeix-hi el curri i remena un minut més.",
"Vierte la leche de coco, mezcla bien y rasca el fondo de la sartén para que el curry se reparta.": "Aboca-hi la llet de coco, barreja-ho bé i rasca el fons de la paella perquè el curri es reparteixi.",
"Deja que la salsa cueza a fuego lento hasta que espese un poco. Si se seca, añade un chorrito de agua.": "Deixa que la salsa bulli a foc lent fins que espesseixi una mica. Si s'asseca, afegeix-hi un raig d'aigua.",
"Sirve el pollo con el arroz al lado y, si tienes, un poco de cilantro por encima.": "Serveix el pollastre amb l'arròs al costat i, si en tens, una mica de coriandre per sobre.",
