"La semana empieza el": "La setmana comença el",
"Lunes": "Dilluns",
"Domingo": "Diumenge",
"Año de nacimiento<small>Para compararte con los de tu edad en los rankings. Se ve tu categoría, no el año.</small>": "Any de naixement<small>Per comparar-te amb els de la teva edat als rànquings. Es veu la teva categoria, no l'any.</small>",
"Año de nacimiento": "Any de naixement",
"Quitado.": "Tret.",
"No se ha podido guardar. Prueba en un rato.": "No s'ha pogut desar. Prova-ho d'aquí a una estona.",
"Qué entrenas<small>Tus ligas. La de fuerza es la de todos.</small>": "Què entrenes<small>Les teves lligues. La de força és la de tothom.</small>",
"Tu peso de cada semana, mejor en {pag}, en «Cuerpo»: así ves cómo cambia.": "El teu pes de cada setmana, millor a {pag}, a «Cos»: així veus com canvia.",
"Modo<small>La Noche, oscura, o el Día, claro, con tus colores en los dos. Automático va con el modo de tu móvil.</small>": "Mode<small>La Nit, fosca, o el Dia, clar, amb els teus colors en tots dos. Automàtic segueix el mode del teu mòbil.</small>",
"Barra de la multipower<small>Cuenta en el peso que apuntas. Cada una pesa distinto, así que pregunta en tu gimnasio o mira la etiqueta.</small>": "Barra de la multipower<small>Compta dins del pes que apuntes. Cadascuna pesa diferent, així que pregunta al teu gimnàs o mira l'etiqueta.</small>",
"Elige qué quieres apuntar. Lo verás en {pag}, en «Cuerpo». El peso va siempre.": "Tria què vols apuntar. Ho veuràs a {pag}, a «Cos». El pes hi va sempre.",
"Formulario de desistimiento": "Formulari de desistiment",
"Cómo calculamos": "Com calculem",
"Estadísticas de uso<small>Qué pantallas y botones se usan, sin saber quién eres.</small>": "Estadístiques d'ús<small>Quines pantalles i quins botons es fan servir, sense saber qui ets.</small>",
"Estadísticas de uso": "Estadístiques d'ús",
"Para cualquier duda, escríbenos a <a href=\"mailto:hola@klonk.fit\">hola@klonk.fit</a>.": "Per a qualsevol dubte, escriu-nos a <a href=\"mailto:hola@klonk.fit\">hola@klonk.fit</a>.",
"Lo ganas al llegar a {d}.": "El guanyes quan arribes a {d}.",
"{n} minutos": "{n} minuts",
"Tu nutrición, con KLONK PRO": "La teva nutrició, amb KLONK PRO",
"Apuntas lo que comes, KLONK te suma la proteína del día y tienes tu menú. Lo que ya apuntaste sigue guardado.": "Apuntes el que menges, KLONK et suma la proteïna del dia i tens el teu menú. El que ja has apuntat continua desat.",
"El oro llega en el momento. Tienes 14 días para desistir del oro que no hayas gastado. <a href=\"condiciones/\" target=\"_blank\" rel=\"noopener\">Condiciones de uso</a>": "L'or arriba al moment. Tens 14 dies per desistir de l'or que no hagis gastat. <a href=\"condiciones/\" target=\"_blank\" rel=\"noopener\">Condicions d'ús</a>",
"Sin conexión. Puedes leerlo en la web:": "Sense connexió. Pots llegir-ho al web:",
