"Rangos de repeticiones": "Rangs de repeticions",
"1 serie": "1 sèrie",
"Llegaste al máximo de cada serie: hoy sube un {pct} %, redondeado a lo que se puede cargar, y cada serie vuelve a su mínimo.": "Vas arribar al màxim de cada sèrie: avui puja un {pct} %, arrodonit al que es pot carregar, i cada sèrie torna al seu mínim.",
"Llegaste al máximo de cada serie. Tienes activado esperar a dos entrenos seguidos: repítelo hoy y la próxima vez sube.": "Vas arribar al màxim de cada sèrie. Tens activat esperar dos entrenaments seguits: repeteix-lo avui i la propera vegada puja.",
"No llegaste al mínimo en ninguna serie: hoy baja un {pct} % para hacerlo bien.": "No vas arribar al mínim a cap sèrie: avui baixa un {pct} % per fer-ho bé.",
"Hace {n} semanas que no lo haces: hoy empiezas un {pct} % más ligero y con el mínimo de cada serie. Si vas sobrado, súbelo tú.": "Fa {n} setmanes que no el fas: avui comences un {pct} % més lleuger i amb el mínim de cada sèrie. Si vas sobrat, puja'l tu.",
"El mismo peso y una repetición más en la serie {serie}, hasta {max}. Cuando llegues al máximo de cada serie, sube el peso.": "El mateix pes i una repetició més a la sèrie {serie}, fins a {max}. Quan arribis al màxim de cada sèrie, puja el pes.",
"El mismo peso: llega al máximo de cada serie y la próxima vez sube.": "El mateix pes: arriba al màxim de cada sèrie i la propera vegada puja.",
"¿Cuántas más podías?": "Quantes més en podies fer?",
"En la última serie de {n}": "A l'última sèrie de {n}",
"Ninguna más": "Cap més",
