"¿Borrar esta medida?": "Esborrar aquesta mesura?",
"No se puede deshacer.": "No es pot desfer.",
"No se puede deshacer. Borrar la cuenta no cancela tu suscripción del App Store. Cancélala antes en los Ajustes del iPhone, en tu nombre y Suscripciones.": "No es pot desfer. Esborrar el compte no cancel·la la teva subscripció de l'App Store. Cancel·la-la abans als Ajustos de l'iPhone, al teu nom i Subscripcions.",
"¿Borrar «{n}»?": "Esborrar «{n}»?",
"Lo que ya apuntaste se queda.": "El que ja has apuntat es queda.",
"¿Quitar esta comida del día?": "Treure aquest àpat del dia?",
"Tu multipower pesa {b} kg y menos no se puede. Si la tuya pesa otra cosa, cámbialo en Ajustes, en «Tu gimnasio».": "La teva multipower pesa {b} kg i menys no es pot. Si la teva pesa una altra cosa, canvia-ho a Configuració, a «El teu gimnàs».",
"1 rep en la serie {n}": "1 rep a la sèrie {n}",
"Menos de 16": "Menys de 16",
"De 16 a 17": "De 16 a 17",
"Acepto las <a href=\"condiciones/\" target=\"_blank\" rel=\"noopener\">condiciones de uso</a>. Cómo tratamos tus datos lo explica la <a href=\"privacidad/\" target=\"_blank\" rel=\"noopener\">política de privacidad</a>.": "Accepto les <a href=\"condiciones/\" target=\"_blank\" rel=\"noopener\">condicions d'ús</a>. Com tractem les teves dades ho explica la <a href=\"privacidad/\" target=\"_blank\" rel=\"noopener\">política de privacitat</a>.",
"KLONK es a partir de 16 años.": "KLONK és a partir de 16 anys.",
"KLONK es a partir de 16 años. Cuando los tengas, aquí te esperamos.": "KLONK és a partir de 16 anys. Quan els tinguis, aquí t'esperem.",
"Para crear la cuenta tienes que aceptar las condiciones de uso.": "Per crear el compte has d'acceptar les condicions d'ús.",
"Lo que pasa a PRO te sigue abierto hasta el {d} de {mes}.": "El que passa a PRO continua obert per a tu fins al {d} de {mes}.",
"Si ya usabas KLONK, lo que pasa a PRO te sigue abierto 30 días.": "Si ja feies servir KLONK, el que passa a PRO continua obert per a tu 30 dies.",
"Hemos cambiado las condiciones": "Hem canviat les condicions",
"Las nuevas explican cómo te avisaremos si vuelven a cambiar.": "Les noves expliquen com t'avisarem si tornen a canviar.",
"KLONK PRO ya se vende: 9,99 € al mes o 39,99 € al año.": "KLONK PRO ja es ven: 9,99 € al mes o 39,99 € a l'any.",
"También cambia cómo desistir del PRO y del oro, y cómo te avisaremos de los próximos cambios.": "També canvia com desistir del PRO i de l'or, i com t'avisarem dels propers canvis.",
"Si no las aceptas, puedes descargar tus datos y borrar tu cuenta desde Ajustes.": "Si no les acceptes, pots baixar les teves dades i esborrar el teu compte des de Configuració.",
"Contar en las estadísticas de KLONK<small>Eres del equipo. Si lo activas, tu cuenta entra en nuestras estadísticas internas como la de un adulto, siempre en números de cinco personas o más. Lo quitas cuando quieras.</small>": "Comptar a les estadístiques de KLONK<small>Ets de l'equip. Si ho actives, el teu compte entra a les nostres estadístiques internes com el d'un adult, sempre en xifres de cinc persones o més. Ho treus quan vulguis.</small>",
"Contar en las estadísticas de KLONK": "Comptar a les estadístiques de KLONK",
