"{preu} € al mes o {preuAny} € al año, con el IVA incluido. El anual empieza con 7 días gratis la primera vez: si lo cancelas antes, no pagas nada. Se renueva cada mes o cada año.": "{preu} € al mes o {preuAny} € a l'any, amb l'IVA inclòs. L'anual comença amb 7 dies gratis la primera vegada: si el cancel·les abans, no pagues res. Es renova cada mes o cada any.",
"¿Cómo pago en el iPhone?": "Com pago a l'iPhone?",
"Con tarjeta, en la página de pago de Stripe. Si tu móvil tiene Apple Pay o Google Pay, Stripe te lo ofrece allí mismo. Ni Apple ni Google cobran nada aparte.": "Amb targeta, a la pàgina de pagament de Stripe. Si el teu mòbil té Apple Pay o Google Pay, Stripe te l'ofereix allà mateix. Ni Apple ni Google cobren res a part.",
"Aquí mismo, con «Cancelar la suscripción». Sigues con PRO hasta el final del periodo que has pagado, y no se renueva.": "Aquí mateix, amb «Cancel·la la subscripció». Continues amb PRO fins al final del període que has pagat, i no es renova.",
"Tienes 14 días para desistir, con el botón «Desistir del contrato aquí» de esta página. Los días gratis no se pagan nunca; del resto, como nos pides empezar ya, pagas solo los días que lo has tenido y te devolvemos lo demás.": "Tens 14 dies per desistir, amb el botó «Desisteix del contracte aquí» d'aquesta pàgina. Els dies gratis no es paguen mai; dels altres, com que ens demanes començar ja, només pagues els dies que l'has tingut i et tornem la resta.",
"No se borra nada. Te quedas con un mazo y {n} entrenos en uso, los que elijas, y con el último mes de historial. Lo demás queda guardado y vuelve si vuelves a PRO.": "No s'esborra res. Et quedes amb una baralla i {n} entrenaments en ús, els que triïs, i amb l'últim mes d'historial. La resta queda desada i torna si tornes a PRO.",
"Estás en tus días gratis de KLONK PRO. El {d} de {mes} se cobran {x} €.": "Ets als dies gratis de KLONK PRO. El {d} de {mes} es cobren {x} €.",
"Tienes KLONK PRO mensual, a {x} € al mes. Se renueva el {d} de {mes}.": "Tens KLONK PRO mensual, a {x} € al mes. Es renova el {d} de {mes}.",
"Tienes KLONK PRO anual, a {x} € al año. Se renueva el {d} de {mes}.": "Tens KLONK PRO anual, a {x} € a l'any. Es renova el {d} de {mes}.",
"Tienes KLONK PRO mensual. Se renueva el {d} de {mes}.": "Tens KLONK PRO mensual. Es renova el {d} de {mes}.",
"Tienes KLONK PRO anual. Se renueva el {d} de {mes}.": "Tens KLONK PRO anual. Es renova el {d} de {mes}.",
"No hemos podido cobrar la renovación. Lo volveremos a intentar estos días, y tu PRO sigue hasta el {d} de {mes}. Si necesitas cambiar de tarjeta, escríbenos a hola@klonk.fit.": "No hem pogut cobrar la renovació. Ho tornarem a provar aquests dies, i el teu PRO continua fins al {d} de {mes}. Si has de canviar de targeta, escriu-nos a hola@klonk.fit.",
"Elige el plan": "Tria el pla",
"{preuAny} € al año": "{preuAny} € a l'any",
"{n} días gratis, y ahorras un {estalvi} %": "{n} dies gratis, i estalvies un {estalvi} %",
