"Sin permanencia": "Sense permanència",
"Tu desistimiento se quedó a medias. Vuelve a pulsar el botón para terminarlo: lo que ya está hecho no se repite.": "El desistiment es va quedar a mig fer. Torna a prémer el botó per acabar-lo: el que ja està fet no es repeteix.",
"Puedes desistir hasta el {d} de {mes}. El PRO se acaba en el momento y te devolvemos la parte que no has usado.": "Pots desistir fins al {d} de {mes}. El PRO s'acaba al moment i et tornem la part que no has fet servir.",
"Esto es lo que tienes:": "Això és el que tens:",
"{preu} € al mes o {preuAny} € al año. Esto es lo que incluye:": "{preu} € al mes o {preuAny} € a l'any. Això és el que inclou:",
"Aún no está a la venta. Saldrá a {preu} € al mes o {preuAny} € al año, con esto:": "Encara no està a la venda. Sortirà a {preu} € al mes o {preuAny} € a l'any, amb això:",
"Contrato: KLONK PRO. El PRO se acaba ahora. Estás en los días gratis: no se te cobrará nada.": "Contracte: KLONK PRO. El PRO s'acaba ara. Ets als dies gratis: no et cobrarem res.",
"Contrato: KLONK PRO. El PRO se acaba ahora y te devolvemos la parte del periodo que no has usado, en el mismo medio de pago.": "Contracte: KLONK PRO. El PRO s'acaba ara i et tornem la part del període que no has fet servir, amb el mateix mitjà de pagament.",
"Tu PRO termina ahora y no volveremos a intentar el cobro. No se borra nada.": "El teu PRO s'acaba ara i no tornarem a intentar el cobrament. No s'esborra res.",
"Sigues con PRO hasta el {d} de {mes} y no se te cobrará nada.": "Continues amb PRO fins al {d} de {mes} i no et cobrarem res.",
"Marca la casilla para empezar ya con KLONK PRO.": "Marca la casella per començar ja amb KLONK PRO.",
"KLONK PRO se volverá a renovar.": "KLONK PRO es tornarà a renovar.",
"Hecho: has desistido. No se te ha cobrado nada y ya no se te cobrará.": "Fet: has desistit. No t'hem cobrat res i ja no et cobrarem.",
"Hecho: suscripción cancelada.": "Fet: subscripció cancel·lada.",
"Hecho: no se te cobrará nada.": "Fet: no et cobrarem res.",
"La ropa de KLONK. Resérvala con tu talla: no pagas nada y te avisamos cuando esté a la venta. El envío, 4,95 €, y gratis desde 75 €.": "La roba de KLONK. Reserva-la amb la teva talla: no pagues res i t'avisem quan estigui a la venda. L'enviament, 4,95 €, i gratis a partir de 75 €.",
