// obreReportIA; compte.js, filesIA
"La hace Claude, la IA de Anthropic. Para hacerla, y revisarla cada domingo, le enviamos lo que pones en el formulario, la rutina que tienes y las series que has hecho de cada músculo en las últimas cuatro semanas.": "La fa Claude, la IA d'Anthropic. Per fer-la, i revisar-la cada diumenge, li enviem el que poses al formulari, la rutina que tens i les sèries que has fet de cada múscul les últimes quatre setmanes.",
"Nunca enviamos tu nombre, tu correo, tu peso ni tus fotos. Puedes quitar el permiso en Ajustes, en «Tu cuenta».": "No enviem mai el teu nom, el teu correu, el teu pes ni les teves fotos. Pots retirar el permís a Configuració, a «El teu compte».",
"Platos con IA": "Plats amb IA",
"Los hace Claude, la IA de Anthropic. Para leer tu plato o proponerte uno, le enviamos las fotos que elijas y lo que le pides: lo que escribes, lo que tienes en casa, la comida, las raciones y el reparto de proteína, hidratos y grasas.": "Els fa Claude, la IA d'Anthropic. Per llegir el teu plat o proposar-te'n un, li enviem les fotos que triïs i el que li demanes: el que escrius, el que tens a casa, l'àpat, les racions i el repartiment de proteïna, hidrats i greixos.",
"No guardamos las fotos, y nunca enviamos tu nombre, tu correo ni tus calorías. Puedes quitar el permiso en Ajustes, en «Tu cuenta».": "No desem les fotos, i no enviem mai el teu nom, el teu correu ni les teves calories. Pots retirar el permís a Configuració, a «El teu compte».",
