"Tus marcas y tu constancia": "Les teves marques i la teva constància",
"Ahora no podemos mostrar los precios del App Store. Prueba en un rato.": "Ara no podem ensenyar els preus de l'App Store. Prova-ho d'aquí a una estona.",
"Con tu cuenta de Apple. Solo pueden comprar las personas mayores de edad. El oro no compra nivel: el nivel solo sube entrenando.": "Amb el teu compte d'Apple. Només poden comprar les persones majors d'edat. L'or no compra nivell: el nivell només puja entrenant.",
"El oro llega en el momento. Lo que compras en el iPhone se devuelve a través de Apple. <a href=\"condiciones/\" target=\"_blank\" rel=\"noopener\">Condiciones de uso</a>": "L'or arriba al moment. El que compres a l'iPhone es torna a través d'Apple. <a href=\"condiciones/\" target=\"_blank\" rel=\"noopener\">Condicions d'ús</a>",
"Todo tu historial, tu nutrición y más.": "Tot el teu historial, la teva nutrició i més.",
"Solo puedes invitar a amigos tuyos que no estén ya en una squad.": "Només pots convidar amics teus que no siguin ja en una squad.",
"Bloquear a quien la vende": "Bloqueja qui la ven",
"¿Bloquear a quien la vende?": "Vols bloquejar qui la ven?",
"No verás sus rutinas ni podrá enviarte nada. No se lo decimos.": "No veuràs les seves rutines ni et podrà enviar res. No l'hi diem.",
"Has bloqueado a quien la vende. Lo quitas cuando quieras en Ajustes.": "Has bloquejat qui la ven. Ho pots treure quan vulguis a Configuració.",
"Gestionar la suscripción": "Gestiona la subscripció",
"Tu suscripción es del App Store. Se gestiona en los Ajustes del iPhone, en tu nombre y Suscripciones.": "La teva subscripció és de l'App Store. Es gestiona a la Configuració de l'iPhone, al teu nom i Subscripcions.",
