"Hoy no pagas nada. Al acabar los {n} días, Apple te cobra {x} al año, y se renueva cada año.": "Avui no pagues res. Quan acabin els {n} dies, Apple et cobra {x} l'any, i es renova cada any.",
"Apple te cobra {x} al año, y se renueva cada año.": "Apple et cobra {x} l'any, i es renova cada any.",
"Apple te cobra {x} al mes, y se renueva cada mes.": "Apple et cobra {x} al mes, i es renova cada mes.",
"{x} al año": "{x} l'any",
