"{x} al mes": "{x} al mes",
"El pago se carga en tu cuenta de Apple al confirmar. La suscripción se renueva sola si no la cancelas al menos 24 horas antes de que acabe el periodo, en los Ajustes del iPhone, en tu nombre y Suscripciones.": "El pagament es carrega al teu compte d'Apple quan confirmes. La subscripció es renova sola si no la cancel·les almenys 24 hores abans que s'acabi el període, a la Configuració de l'iPhone, al teu nom i Subscripcions.",
"Términos de Apple (EULA)": "Termes d'Apple (EULA)",
"En los Ajustes del iPhone, en tu nombre y Suscripciones, o con «Gestionar la suscripción» en esta página. Sigues con PRO hasta el final del periodo que has pagado.": "A la Configuració de l'iPhone, al teu nom i Subscripcions, o amb «Gestiona la subscripció» en aquesta pàgina. Segueixes amb PRO fins al final del període que has pagat.",
"Lo que compras en el iPhone se devuelve a través de Apple, en reportaproblem.apple.com. Lo que Apple devuelve deja de valer en KLONK.": "El que compres a l'iPhone es torna a través d'Apple, a reportaproblem.apple.com. El que Apple torna deixa de valer a KLONK.",
"Apple, con tu cuenta del App Store. KLONK no ve tu tarjeta.": "Apple, amb el teu compte de l'App Store. KLONK no veu la teva targeta.",
"No se ha podido hacer la compra y no se ha cobrado nada. Prueba otra vez en un rato.": "No s'ha pogut fer la compra i no s'ha cobrat res. Torna-ho a provar d'aquí a una estona.",
"La compra espera una aprobación. Cuando Apple la confirme, la verás en KLONK.": "La compra espera una aprovació. Quan Apple la confirmi, la veuràs a KLONK.",
"Esta compra de Apple es de otra cuenta de KLONK.": "Aquesta compra d'Apple és d'un altre compte de KLONK.",
"Apple ha hecho la compra, pero aún no hemos podido confirmarla. Lo volveremos a intentar al abrir KLONK.": "Apple ha fet la compra, però encara no l'hem pogut confirmar. Ho tornarem a provar quan obris KLONK.",
"No hemos podido hablar con el App Store. Prueba otra vez en un rato.": "No hem pogut parlar amb l'App Store. Torna-ho a provar d'aquí a una estona.",
"Ya tienes KLONK PRO.": "Ja tens KLONK PRO.",
