"No hay ninguna suscripción de KLONK PRO en esta cuenta de Apple.": "No hi ha cap subscripció de KLONK PRO en aquest compte d'Apple.",
"No hemos podido abrir el App Store. Puedes gestionarla en Ajustes del iPhone, en tu nombre, Suscripciones.": "No hem pogut obrir l'App Store. La pots gestionar a la Configuració de l'iPhone, al teu nom, Subscripcions.",
