"La vez pasada llegaste al máximo de cada serie con {a} kg de ayuda. Hoy bajas a {b} kg de ayuda, y eso es la sobrecarga progresiva.": "L'última vegada vas arribar al màxim de cada sèrie amb {a} kg d'ajuda. Avui baixes a {b} kg d'ajuda, i això és la sobrecàrrega progressiva.",
"Hace semanas que no lo haces. Hoy, {b} kg de ayuda para volver con calma.": "Fa setmanes que no el fas. Avui, {b} kg d'ajuda per tornar-hi amb calma.",
"La vez pasada no llegaste al mínimo con {a} kg de ayuda. Hoy subes a {b} kg de ayuda para hacerlo bien.": "L'última vegada no vas arribar al mínim amb {a} kg d'ajuda. Avui puges a {b} kg d'ajuda per fer-ho bé.",
