"Es la primera vez. Aguanta lo que puedas, entre {min} y {max} segundos, sin perder la postura. La próxima vez, la app te propone el tiempo.": "És la primera vegada. Aguanta el que puguis, entre {min} i {max} segons, sense perdre la postura. La propera vegada, l'app et proposa el temps.",
"Aguantaste {max} s en todas las series: hoy, 5 segundos más en cada una.": "Vas aguantar {max} s a totes les sèries: avui, 5 segons més a cadascuna.",
"El mismo tiempo que la última vez: llega a {max} s en todas las series y la próxima vez sube.": "El mateix temps que l'última vegada: arriba a {max} s a totes les sèries i la propera vegada puja.",
