// (29-10-2026, la fase 11) el full de l'activitat lligada al compte (nit.js, demanaUs) i el seu interruptor a Ajustes
"Ayúdanos a mejorar KLONK": "Ajuda'ns a millorar KLONK",
"Si dices que sí, guardamos con tu cuenta qué pantallas abres, cuánto rato, qué botones tocas, cuándo entrenas y los errores de la app. Así vemos dónde se atasca la gente y lo arreglamos. No lo vendemos ni lo cruzamos con nada.": "Si dius que sí, desem amb el teu compte quines pantalles obres, quanta estona, quins botons toques, quan entrenes i els errors de l'app. Així veiem on s'encalla la gent i ho arreglem. No ho venem ni ho creuem amb res.",
"Lo quitas cuando quieras en Ajustes, en «Legal y privacidad», y lo borramos.": "Ho treus quan vulguis a Configuració, a «Legal i privacitat», i ho esborrem.",
"Sí, vale": "Sí, d'acord",
"Tu actividad en la app<small>Lo que haces en KLONK, guardado con tu cuenta para mejorarla.</small>": "La teva activitat a l'app<small>El que fas a KLONK, desat amb el teu compte per millorar-la.</small>",
"Tu actividad en la app": "La teva activitat a l'app",
"Guardamos tu actividad con tu cuenta. Gracias.": "Desem la teva activitat amb el teu compte. Gràcies.",
"Ya no guardamos tu actividad, y la hemos borrado.": "Ja no desem la teva activitat, i l'hem esborrada.",
"Widget de tu semana<small>En la pantalla de inicio: los días que has ido y los que te faltan.</small>": "Widget de la teva setmana<small>A la pantalla d'inici: els dies que hi has anat i els que et falten.</small>",
// (21-10-2026, web-02) els textos nous de les tandes del triatge del 18-10 (A1 a A17, A2b, A2c, C1, S0 a S9); sense revisar per l'Albert
"Adrià es el más alto, aunque es el pequeño, y el que nos dice cuándo algo queda feo o da cringe. Àlex es el más fuerte (natural) y el que más sabe de gym, y también dibuja a los dos personajes de la app. Eric, el primo, la prueba antes que nadie y estudia para ser fisio. Albert es el hermano mayor. La app la monta él.": "L'Adrià és el més alt, tot i que és el petit, i el que ens diu quan una cosa queda lletja o fa cringe. L'Àlex és el més fort (natural) i el que més sap de gimnàs, i també dibuixa els dos personatges de l'app. L'Eric, el cosí, la prova abans que ningú i estudia per ser fisio. L'Albert és el germà gran. L'app la munta ell.",
"Sí a las novedades": "Sí a les novetats",
"Sí a las ofertas": "Sí a les ofertes",
"Con tarjeta. Solo pueden comprar las personas mayores de edad. El oro no compra nivel: los personajes buenos siguen pidiendo entrenar.": "Amb targeta. Només poden comprar les persones majors d'edat. L'or no compra nivell: els personatges bons encara demanen entrenar.",
"Si sales sin guardar, pierdes lo que has escrito.": "Si surts sense desar, perds el que has escrit.",
"¿Guardar tus medidas?": "Desar les teves mesures?",
"Cambiar por otro": "Canvia'l per un altre",
"El cronómetro se quedó en marcha ({t}). Escribe los segundos que aguantaste.": "El cronòmetre es va quedar en marxa ({t}). Escriu els segons que vas aguantar.",
"¿{reps} repeticiones?": "{reps} repeticions?",
"¿{kg} kg × {reps}?": "{kg} kg × {reps}?",
"Es mucho más de lo que has hecho en {n}. Si es un error, corrígelo antes de marcarla.": "És molt més del que has fet en {n}. Si és un error, corregeix-ho abans de marcar-la.",
"Son muchas repeticiones para una serie. Si es un error, corrígelo antes de marcarla.": "Són moltes repeticions per a una sèrie. Si és un error, corregeix-ho abans de marcar-la.",
"Es más que el récord del mundo. Si es un error, corrígelo antes de marcarla.": "És més que el rècord del món. Si és un error, corregeix-ho abans de marcar-la.",
"Son más de 500 kg. Si es un error, corrígelo antes de marcarla.": "Són més de 500 kg. Si és un error, corregeix-ho abans de marcar-la.",
