"Falta la clave.": "Falta la clau.",
"Clave no válida.": "Clau no vàlida.",
"Ese aviso no existe.": "Aquest avís no existeix.",
"Ya no se puede usar KLONK sin cuenta. Crea una cuenta o entra en la tuya.": "Ja no es pot fer servir KLONK sense compte. Crea un compte o entra al teu.",
"Ese nickname no vale: de 3 a 20 letras o números, sin espacios.": "Aquest nickname no val: de 3 a 20 lletres o números, sense espais.",
"Ranking desconocido.": "Rànquing desconegut.",
"Ahora no podemos comprobar la dirección. Prueba en un rato.": "Ara no podem comprovar l'adreça. Prova-ho d'aquí a una estona.",
"Solo para mayores de edad.": "Només per a majors d'edat.",
"Ese año no vale.": "Aquest any no val.",
"No existe.": "No existeix.",
"Has bloqueado a esta persona. Para ver su perfil, quita el bloqueo en Ajustes.": "Has bloquejat aquesta persona. Per veure el seu perfil, treu el bloqueig a Configuració.",
"Este perfil es privado.": "Aquest perfil és privat.",
"Los códigos ya no se usan: envía una solicitud con su nickname en Social, Clan.": "Els codis ja no es fan servir: envia una sol·licitud amb el seu nickname a Social, Clan.",
"Ese nombre no vale.": "Aquest nom no val.",
"Ese nombre lleva una palabra que no se puede usar.": "Aquest nom porta una paraula que no es pot fer servir.",
"Ya has añadido cinco gimnasios. Si falta alguno más, escríbenos a hola@klonk.fit.": "Ja has afegit cinc gimnasos. Si en falta algun més, escriu-nos a hola@klonk.fit.",
"No encontramos esa dirección. Escríbela con la calle, el número y la ciudad.": "No trobem aquesta adreça. Escriu-la amb el carrer, el número i la ciutat.",
"No encontramos ese gimnasio.": "No trobem aquest gimnàs.",
"Los pagos aún no están activos.": "Els pagaments encara no estan actius.",
"No hemos podido abrir el pago y no se ha cobrado nada. Prueba otra vez en un rato.": "No hem pogut obrir el pagament i no s'ha cobrat res. Torna-ho a provar d'aquí a una estona.",
"Ese producto no existe.": "Aquest producte no existeix.",
"Esa talla no existe.": "Aquesta talla no existeix.",
"Aún no has desbloqueado esta línea.": "Encara no has desbloquejat aquesta línia.",
"La suscripción de avisos no es válida.": "La subscripció d'avisos no és vàlida.",
"Este navegador da una dirección de avisos que no conocemos.": "Aquest navegador dona una adreça d'avisos que no coneixem.",
"Ese descanso no vale.": "Aquest descans no val.",
"Hoy ya has avisado a tu clan.": "Avui ja has avisat el teu clan.",
"Primero elige tu nickname.": "Primer tria el teu nickname.",
"Has bloqueado a esta persona. Para enviarle una solicitud, quita el bloqueo en Ajustes.": "Has bloquejat aquesta persona. Per enviar-li una sol·licitud, treu el bloqueig a Configuració.",
"No puedes enviarle una solicitud.": "No li pots enviar una sol·licitud.",
"Tienes muchas solicitudes sin respuesta. Espera a que te acepten.": "Tens moltes sol·licituds sense resposta. Espera que t'acceptin.",
"Esa solicitud ya no está.": "Aquesta sol·licitud ja no hi és.",
"Ese marco no existe.": "Aquest marc no existeix.",
"Ese marco aún no lo has ganado.": "Aquest marc encara no l'has guanyat.",
"Solo puedes enviarla a alguien de tu clan.": "Només la pots enviar a algú del teu clan.",
"Ya tiene su mazo: envíale un entreno.": "Ja té la seva baralla: envia-li un entrenament.",
"La base de alimentos no está disponible ahora mismo.": "La base d'aliments no està disponible ara mateix.",
"Ese código de barras no es válido.": "Aquest codi de barres no és vàlid.",
"Ahora no podemos mirar ese código. Prueba en un minuto.": "Ara no podem mirar aquest codi. Prova-ho d'aquí a un minut.",
"Ese producto no está en la base.": "Aquest producte no és a la base.",
"Escribe el nombre del alimento.": "Escriu el nom de l'aliment.",
"Ha tardado demasiado. Prueba con una foto más cerca de la tabla.": "Ha trigat massa. Prova amb una foto més a prop de la taula.",
"Esa imagen no se puede leer. Prueba con una foto normal de la cámara.": "Aquesta imatge no es pot llegir. Prova amb una foto normal de la càmera.",
"Para leer etiquetas hace falta una cuenta.": "Per llegir etiquetes cal un compte.",
"La foto pesa demasiado.": "La foto pesa massa.",
"Eso no es una foto (JPEG, PNG o WebP).": "Això no és una foto (JPEG, PNG o WebP).",
"Ahora hay mucha gente leyendo etiquetas. Prueba en un momento.": "Ara hi ha molta gent llegint etiquetes. Prova-ho d'aquí a un moment.",
"Ese archivo tarda demasiado en leerse. Prueba con una captura de la rutina.": "Aquest fitxer triga massa a llegir-se. Prova amb una captura de la rutina.",
"Ese archivo no lo sabemos leer. Haz una captura de la rutina o copia su texto.": "Aquest fitxer no el sabem llegir. Fes una captura de la rutina o copia'n el text.",
"Para importar rutinas hace falta una cuenta.": "Per importar rutines cal un compte.",
"Ahora hay mucha gente importando. Prueba en un momento.": "Ara hi ha molta gent important. Prova-ho d'aquí a un moment.",
"En ese archivo no hay texto que leer. Si es una foto o un PDF escaneado, haz una captura nítida.": "En aquest fitxer no hi ha text per llegir. Si és una foto o un PDF escanejat, fes una captura nítida.",
"Para pedirnos un ejercicio hace falta una cuenta.": "Per demanar-nos un exercici cal un compte.",
"Hoy ya nos has pedido muchos. Mañana más.": "Avui ja ens n'has demanat molts. Demà més.",
"No te puedes bloquear.": "No et pots bloquejar.",
