"No puedes usar esta invitación.": "No pots fer servir aquesta invitació.",
"Esta invitación ya está completa. Pídele otra.": "Aquesta invitació ja està completa. Demana-li'n una altra.",
"Has bloqueado a esta persona. Para pedirle entrar en su clan, quita el bloqueo en Ajustes.": "Has bloquejat aquesta persona. Per demanar-li entrar al seu clan, treu el bloqueig a Configuració.",
