"Esa reacción no existe.": "Aquesta reacció no existeix.",
"Ese entreno no está en tu clan.": "Aquest entrenament no és al teu clan.",
"No puedes reaccionar a tus entrenos.": "No pots reaccionar als teus entrenaments.",
"No hemos podido comprobar la compra con Apple. Prueba otra vez en un rato.": "No hem pogut comprovar la compra amb Apple. Torna-ho a provar d'aquí a una estona.",
"Esta compra no la ha firmado Apple para KLONK.": "Aquesta compra no l'ha signada Apple per a KLONK.",
"Este producto no es de KLONK.": "Aquest producte no és de KLONK.",
