"Ese código no vale. Revísalo o pídele otro a quien te lo pasó.": "Aquest codi no val. Revisa'l o demana'n un altre a qui te'l va passar.",
"Por ahora, KLONK es solo con invitación: para crear tu cuenta necesitas la de un amigo o el enlace de un creador.": "De moment, KLONK només és amb invitació: per crear el teu compte necessites la d'un amic o l'enllaç d'un creador.",
