"Falta la cuenta de Google.": "Falta el compte de Google.",
"Ese correo ya está unido a otra cuenta de Google.": "Aquest correu ja està unit a un altre compte de Google.",
"Faltan datos para crear la cuenta.": "Falten dades per crear el compte.",
"El enlace ha caducado. Pide otro.": "L'enllaç ha caducat. Demana'n un altre.",
